// GoldenFileComparator is abstract; subclass LocalFileComparator to add tolerance.
class TolerantComparator extends LocalFileComparator {
  TolerantComparator(super.testFile, {this.threshold = 0.005});
  final double threshold;

  @override
  Future<bool> compare(Uint8List imageBytes, Uri golden) async {
    final result = await GoldenFileComparator.compareLists(
      imageBytes, await getGoldenBytes(golden));
    if (result.passed || result.diffPercent <= threshold) return true;
    throw FlutterError(result.error);
  }
}

void main() {
  goldenFileComparator = TolerantComparator(
    Uri.parse('test/widgets/product_card_test.dart'),
  );
}

