test('debounce emits once after the quiet period', () {
  fakeAsync((async) {
    final seen = <String>[];
    final search = Debouncer(const Duration(milliseconds: 300));

    search.run(() => seen.add('a'));
    async.elapse(const Duration(milliseconds: 100));
    search.run(() => seen.add('ab'));        // resets the timer
    async.elapse(const Duration(milliseconds: 100));
    expect(seen, isEmpty);                    // still quiet

    async.elapse(const Duration(milliseconds: 300));
    expect(seen, ['ab']);                     // only the last one ran
  });
});

test('retry backs off 1s, 2s, 4s', () {
  fakeAsync((async) {
    var attempts = 0;
    Object? result;

    retry(() async {
      attempts++;
      if (attempts < 4) throw const SocketException('down');
      return 'ok';
    }).then((value) => result = value);

    async.elapse(const Duration(seconds: 1));
    expect(attempts, 2);
    async.elapse(const Duration(seconds: 2));
    expect(attempts, 3);
    async.elapse(const Duration(seconds: 4));
    async.flushMicrotasks();
    expect(result, 'ok');
  });
});

// ── Injecting the clock instead of calling DateTime.now() ──
class TokenStore {
  TokenStore({DateTime Function()? now}) : _now = now ?? DateTime.now;
  final DateTime Function() _now;
  bool isExpired(Token t) => _now().isAfter(t.expiresAt);
}

test('token expiry', () {
  final store = TokenStore(now: () => DateTime(2026, 9, 2, 12));
  expect(store.isExpired(Token(expiresAt: DateTime(2026, 9, 2, 11))), isTrue);
});
